def trap(nums):
    n = len(nums)
    total = 0
    for i in range(n):
        left_max = max(nums[: i + 1]) if i >= 0 else 0
        right_max = max(nums[i:]) if i < n else 0
        water = min(left_max, right_max) - nums[i]
        if water > 0:
            total += water
    return total

