def trap(nums):
    if not nums:
        return 0
    left, right = 0, len(nums) - 1
    left_max = right_max = 0
    total = 0
    while left < right:
        if nums[left] <= nums[right]:
            if nums[left] >= left_max:
                left_max = nums[left]
            else:
                total += left_max - nums[left]
            left += 1
        else:
            if nums[right] >= right_max:
                right_max = nums[right]
            else:
                total += right_max - nums[right]
            right -= 1
    return total
